const a15 = defineCase("A-15", "AS-F-BREAKGLASS", "Create a BreakGlassSession, reject requester and duplicate approvals, obtain two independent active approvals, activate it, check exact and mismatched scopes, then close and expire sessions.", "Exactly two independent approvers produce one READY transition; emergency authority is limited to exact frozen scope, TTL and non-policy fences, terminal sessions never authorize, and no unpublished FINAL snapshot key is assumed.", ["Manager HTTP", "two APIs", "real TTL", "verification snapshot"], async (ctx) => {
  const family = ctx.fixtures.breakglass(); const { apis } = await boot(ctx, { family, apiCount: 2 }); const created = await ctx.createBreakGlass(apis[0].baseUrl, family.breakGlassBody(), { key: ctx.key("breakglass") }); requireStatus(ctx, created, 200, "create BreakGlassSession"); const id = identity(created.json, ["breakGlassSessionId"]); ctx.equal(created.json.requiredApprovals, 2, "quorum fixed at two"); const self = await ctx.approveBreakGlass(apis[1].baseUrl, id, { approverId: family.requester.principalId, decision: "APPROVE", comment: "self" }, { key: ctx.key("self") }); ctx.ok([400, 403, 409].includes(self.status), "requester cannot approve"); const approvalAKey = ctx.key("approval-a"); const first = await ctx.approveBreakGlass(apis[0].baseUrl, id, { approverId: family.reviewerA.principalId, decision: "APPROVE", comment: "reviewed" }, { key: approvalAKey }); requireStatus(ctx, first, 200, "first approval"); const replay = await ctx.approveBreakGlass(apis[1].baseUrl, id, { approverId: family.reviewerA.principalId, decision: "APPROVE", comment: "reviewed" }, { key: approvalAKey }); stableSemantic(ctx, [first, replay], "approval replay"); const second = await ctx.approveBreakGlass(apis[1].baseUrl, id, { approverId: family.reviewerB.principalId, decision: "APPROVE", comment: "independent" }, { key: ctx.key("approval-b") }); requireStatus(ctx, second, 200, "second approval"); const duplicate = await ctx.approveBreakGlass(apis[0].baseUrl, id, { approverId: family.reviewerA.principalId, decision: "APPROVE", comment: "duplicate" }, { key: ctx.key("approval-a-duplicate") }); ctx.equal(duplicate.status, 409, "same approver cannot approve twice"); const active = await ctx.activateBreakGlass(apis[0].baseUrl, id, { expectedState: "READY" }, { key: ctx.key("activate") }); requireStatus(ctx, active, 200, "activate BreakGlassSession"); const allowed = await ctx.checkBreakGlass(apis[1].baseUrl, id, { action: "deploy", resource: "production/service", region: "us-east" }); requireStatus(ctx, allowed, 200, "scope check"); ctx.equal(allowed.json.authorized, true, "exact scope authorized"); for (const body of [{ action: "delete", resource: "production/service", region: "us-east" }, { action: "deploy", resource: "staging/service", region: "us-east" }, { action: "deploy", resource: "production/service", region: "us-west" }]) { const denied = await ctx.checkBreakGlass(apis[1].baseUrl, id, body); requireStatus(ctx, denied, 200, "mismatched check"); ctx.equal(denied.json.authorized, false, "mismatch denied"); } const closed = await ctx.closeBreakGlass(apis[0].baseUrl, id, { reason: "incident resolved" }, { key: ctx.key("close") }); requireStatus(ctx, closed, 200, "close BreakGlassSession"); const after = await ctx.checkBreakGlass(apis[1].baseUrl, id, { action: "deploy", resource: "production/service", region: "us-east" }); ctx.equal(after.json.authorized, false, "closed session cannot authorize"); const expiring = await createReadyBreakGlass(ctx, apis[0].baseUrl, family, { label: "expiry", overrides: { requestedTtlSeconds: 60 } }); const expiryWorker = await ctx.startWorker(); await ctx.sleep(60_200); const expiredCheck = await ctx.checkBreakGlass(apis[1].baseUrl, expiring.breakGlassSessionId, { action: "deploy", resource: "production/service", region: "us-east" }); requireStatus(ctx, expiredCheck, 200, "expired scope check"); ctx.equal(expiredCheck.json.authorized, false, "expired session cannot authorize"); const expiryState = await waitSnapshot(ctx, apis[0].baseUrl, (value) => value.work.some(({ kind, aggregateId, terminal }) => kind === "BREAK_GLASS_EXPIRE" && aggregateId === expiring.breakGlassSessionId && terminal) ? value : undefined, { label: "BreakGlass expiry Work", processes: [expiryWorker] }); return caseResult(ctx, { breakGlassSessionId: id, expiredBreakGlassSessionId: expiring.breakGlassSessionId, approvals: 2, expiryWork: expiryState.work.filter(({ kind }) => kind === "BREAK_GLASS_EXPIRE").length }, [gap("AS-A15-FINAL-SNAPSHOT-KEYS", "AS-GAP-04")]);
});

const a16 = defineCase("A-16", "AS-F-BREAKGLASS", "Quarantine a region with revision CAS, verify ordinary grants and new issuance fail closed, terminate emergency sessions, record an independent retrospective review, and release with guarded CAS.", "Quarantine creates one revision, revokes regional grants and schedules REGION_QUARANTINE Work; stale CAS and premature release are side-effect free, and completed review permits exactly one release without assuming unpublished snapshot key casing.", ["Manager HTTP", "grant checks", "quarantine Work", "verification snapshot"], async (ctx) => {
  const family = ctx.fixtures.breakglass(); const { apis } = await boot(ctx, { family, apiCount: 2 }); const ordinary = await requestRiskGrant(ctx, apis[0].baseUrl, family, "ordinary", { workerCount: 1 }); const emergency = await createReadyBreakGlass(ctx, apis[0].baseUrl, family, { label: "a16" }); const quarantine = await ctx.quarantineRegion(apis[0].baseUrl, "us-east", { tenantId: family.tenant.tenantId, expectedRevision: 0, reason: "active incident", createdBy: family.reviewerC.principalId }, { key: ctx.key("quarantine") }); requireStatus(ctx, quarantine, 200, "quarantine"); ctx.assert("quarantine response exact shape", () => exactKeys(quarantine.json, ["regionalQuarantineId", "tenantId", "region", "revision", "state", "reason", "createdBy", "effectiveAt", "releasedAt", "createdAt", "updatedAt"], "RegionalQuarantine")); const revision = quarantine.json.revision; ctx.equal(revision, 1, "quarantine revision one"); const check = await ctx.checkGrant(apis[1].baseUrl, ordinary.grantId); requireStatus(ctx, check, 200, "ordinary grant after quarantine"); ctx.equal(check.json.active, false, "ordinary grant fails closed", { hardCapIds: ["REVOCATION_FAIL_CLOSED"] }); const postQuarantine = await createRequest(ctx, apis[0].baseUrl, family, "blocked-by-quarantine"); const postRisk = await waitRisk(ctx, apis[0].baseUrl, postQuarantine.accessRequestId, ordinary.workers); const postRequest = byId(postRisk, "accessRequests", "accessRequestId", postQuarantine.accessRequestId); if (["APPROVED", "PENDING_REVIEW"].includes(postRequest.state)) { const attempted = await ctx.grantAccess(apis[1].baseUrl, postQuarantine.accessRequestId, { expectedState: postRequest.state }, { key: ctx.key("quarantined-grant") }); ctx.ok(attempted.status >= 400, "quarantine blocks new ordinary Grant"); } const quarantinedState = await waitSnapshot(ctx, apis[0].baseUrl, (value) => value.work.some(({ kind, terminal }) => kind === "REGION_QUARANTINE" && terminal) ? value : undefined, { label: "quarantine propagation", processes: ordinary.workers }); ctx.equal(resources(quarantinedState, "accessGrants").filter(({ region, state }) => region === "us-east" && state === "ACTIVE").length, 0, "no active ordinary regional Grant"); const stableSurface = (value) => ({ resources: value.resources, events: value.events, workIdentities: value.work.map(({ workId, kind, aggregateId }) => ({ workId, kind, aggregateId })) }); const beforeStale = stableSurface(quarantinedState); const stale = await ctx.quarantineRegion(apis[1].baseUrl, "us-east", { tenantId: family.tenant.tenantId, expectedRevision: 0, reason: "stale", createdBy: family.reviewerC.principalId }, { key: ctx.key("stale-quarantine") }); ctx.equal(stale.status, 409, "stale quarantine CAS"); const premature = await ctx.releaseRegion(apis[1].baseUrl, "us-east", { tenantId: family.tenant.tenantId, expectedRevision: 1, releasedBy: family.reviewerC.principalId }, { key: ctx.key("premature-release") }); ctx.ok([400, 409].includes(premature.status), "premature release blocked"); ctx.equal(stableSurface(await snapshot(ctx, apis[0].baseUrl)), beforeStale, "stale and premature CAS have no side effect"); requireStatus(ctx, await ctx.closeBreakGlass(apis[0].baseUrl, emergency.breakGlassSessionId, { reason: "incident resolved" }, { key: ctx.key("close-emergency") }), 200, "close emergency"); const review = await ctx.reviewRetrospective(apis[0].baseUrl, emergency.breakGlassSessionId, { reviewerId: family.reviewerC.principalId, outcome: "JUSTIFIED", findings: "Emergency response was scoped and reviewed." }, { key: ctx.key("retrospective") }); requireStatus(ctx, review, 200, "retrospective review"); const released = await ctx.releaseRegion(apis[1].baseUrl, "us-east", { tenantId: family.tenant.tenantId, expectedRevision: 1, releasedBy: family.reviewerC.principalId }, { key: ctx.key("release") }); requireStatus(ctx, released, 200, "guarded release"); ctx.equal(released.json.state, "RELEASED", "released state"); const replay = await ctx.releaseRegion(apis[0].baseUrl, "us-east", { tenantId: family.tenant.tenantId, expectedRevision: 1, releasedBy: family.reviewerC.principalId }, { key: ctx.key("second-release") }); ctx.equal(replay.status, 409, "release CAS once"); return caseResult(ctx, { regionalRevision: revision, breakGlassSessionId: emergency.breakGlassSessionId, blockedRequestId: postQuarantine.accessRequestId }, [gap("AS-A16-FINAL-SNAPSHOT-KEYS", "AS-GAP-04")]);
});

function stableSnapshot(value) { const clone = structuredClone(value); delete clone.asOf; if (clone.metrics) delete clone.metrics.databaseBytes; return clone; }

export const A_CASES = Object.freeze([a01, a02, a03, a04, a05, a06, a07, a08, a09, a10, a11, a12, a13, a14, a15, a16]);
